dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/c2ct/1?columns=phenotype",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry*",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "*"
        },
        {
          "label": "AA",
          "value": "AA"
        },
        {
          "label": "EA",
          "value": "EA"
        },
        {
          "label": "EU",
          "value": "EU"
        },
        {
          "label": "HS",
          "value": "HS"
        },
        {
          "label": "SA",
          "value": "SA"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Region",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true"
    },
    {
      "parameter": "bigRegion",
      "label": "Big region",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 2000000
    },
    {
      "parameter": "tissue",
      "label": "Tissue*",
      "type": "api list",
      "data point": {
        "type": "api",
        "url": "https://giant.hugeampkpnbi.org/api/bio/keys/gene-links/2?columns=tissue",
        "data type": "json",
        "data wrapper": [
          "keys"
        ]
      }
    }
  ],
  "visualizer collection": [
    {
      "sections": [
        "associations"
      ],
      "label": "Associated variants in region"
    },
    {
      "sections": [
        "gene_links"
      ],
      "label": "SNP to gene links"
    },
    {
      "sections": [
        "credible_sets_2"
      ],
      "label": "Credible Sets in bigger region"
    }
  ],
  "sections": [
    {
      "section id": "associations",
      "header": "Variants in Credible set region",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data zoom": {
          "chromosome": "chromosome",
          "position": "Position"
        },
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Standard error",
            "raw field": "stdErr",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue",
            "if no value": 0
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "raw",
            "field name": "chr",
            "raw field": "chromosome"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard error",
          "Z Score",
          "Consequence"
        ],
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Beta",
          "label": "Beta (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Z Score",
          "label": "Z Score (>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "dropdown",
          "label in bubble": "true"
        }
      ],
      "filter width": "sm",
      "visualizer": {
        "star key": "Variant ID",
        "zoom": "true",
        "type": "region plot",
        "x axis field": "Position",
        "y axis field": "-log10(P-Value)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p-value)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value",
          "Beta"
        ],
        "height": 120,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "ld server": {
          "pos": "Position",
          "ref": "ref",
          "alt": "alt",
          "ref variant field": "Variant ID",
          "populations field": "P-Value",
          "populations type": "fixed",
          "fixed population": "ALL",
          "populations": {
            "ALL": "ALL"
          }
        },
        "genes track": {
          "input type": "dynamic",
          "dynamic parameter": "region"
        },
        "input type": "dynamic",
        "dynamic parameter": "region",
        "if combine y axis field": {
          "type": "average",
          "field": "-log10(P-Value)"
        }
      }
    },
    {
      "section id": "gene_links",
      "header": "SNP to gene links",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "gene-links",
        "parameters": [
          "tissue",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "regions filter region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              ","
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region center",
            "expression": [
              "(",
              "start",
              "+",
              "end",
              ")",
              "/",
              2
            ]
          },
          {
            "type": "raw",
            "field name": "chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "js math",
            "field name": "Position",
            "raw field": "region center",
            "method": "round"
          },
          {
            "type": "raw",
            "field name": "Biosample",
            "raw field": "biosample",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Biosample ID",
            "raw field": "biosampleId",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "State",
            "raw field": "state",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Source",
            "raw field": "source",
            "if no value": "N/A"
          },
          {
            "type": "join multi",
            "field name": "Source (Method)",
            "fields to join": [
              "Source",
              "Method"
            ],
            "join by": [
              " (",
              ")"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset",
            "if no value": "N/A"
          },
          {
            "type": "raw",
            "field name": "Target gene",
            "raw field": "targetGene",
            "if no value": "N/A"
          },
          {
            "type": "join multi",
            "field name": "Target gene region",
            "fields to join": [
              "targetGeneStart",
              "targetGeneEnd"
            ],
            "join by": [
              "-"
            ]
          }
        ],
        "top rows": [
          "Biosample",
          "Biosample ID",
          "Region",
          "Target gene",
          "Target gene region",
          "State",
          "Method",
          "Source",
          "Dataset"
        ],
        "locus field": "Region",
        "column formatting": {
          "Dataset": {
            "type": [
              "link"
            ],
            "link to": "https://cmdga.org/annotations/",
            "new tab": "true"
          }
        }
      },
      "filters": [
        {
          "field": "Biosample",
          "label": "Biosample",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Target gene",
          "label": "Target gene",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Source",
          "label": "Source",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "search",
          "label in bubble": "true",
          "features": [
            "autocomplete"
          ]
        }
      ],
      "visualizer": {
        "type": "region track",
        "zoom": "true",
        "render by": "Region",
        "x axis field": "Position",
        "y axis field": "Target gene",
        "hover content": [
          "Region",
          "Biosample",
          "Target gene",
          "Target gene region",
          "State",
          "Method",
          "Source",
          "Dataset"
        ],
        "color by": "Source",
        "track height": 12,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        }
      }
    },
    {
      "section id": "credible_sets_2",
      "header": "Credible Sets in bigger region",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "region": "region",
        "expand region by": 2000000,
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "display unused": false,
        "data convert": [
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "start",
              "end"
            ],
            "join by": [
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "end",
              "-",
              "start"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "CS region",
              "region length"
            ],
            "join by": [
              " (",
              "bp)"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "start"
          }
        ],
        "top rows": [
          "CS ID",
          "CS region (length)",
          "Dataset",
          "Method",
          "PMID"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load variants to CS variants table",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      },
      "visualizer": {
        "label": "Grouped by tissues",
        "type": "region track",
        "zoom": "true",
        "render by": "Region",
        "x axis field": "Position",
        "y axis field": "Method",
        "hover content": [
          "CS ID",
          "CS region",
          "Dataset",
          "Method",
          "PMID"
        ],
        "set region parameter by": {
          "field": "CS region",
          "parameter": "region",
          "max region": 200000
        },
        "color by": "Method",
        "track height": 12,
        "plot margin": {
          "left": 200,
          "right": 200,
          "top": 30,
          "bottom": 100,
          "bump": 10
        },
        "expand region by": 2000000
      }
    },
    {
      "section id": "credible_sets_1",
      "header": "Credible Sets in viewing region",
      "data point": {
        "type": "bioindex",
        "url": "https://giant.hugeampkpnbi.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "end",
              "-",
              "start"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "CS region",
              "region length"
            ],
            "join by": [
              " (",
              "bp)"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          }
        ],
        "top rows": [
          "CS ID",
          "CS region (length)",
          "Dataset",
          "Method",
          "PMID"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load variants to CS variants table",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    }
  ],
  "unused": []
}
